import pandas as pd

station_info = feed.station_information
station_status = feed.station_status

station = station_info[station_info['station_id'] == '199130']
status = station_status[station_status['station_id'] == '199130']

if not station.empty and not status.empty:
    capacity = station['capacity'].iloc[0]
    num_bikes_available = status['num_bikes_available'].iloc[0]
    utilization_ratio = num_bikes_available / capacity
    result = {"answer": float(utilization_ratio)}
else:
    result = {"answer": None}
